result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/contingency.py", "content": """"Contingency-table toolkit: chi-squared tests and Fisher's exact test."""

from math import comb


def _check_2x2(table):
    if len(table) != 2 or any(len(row) != 2 for row in table):
        raise ValueError("expected a 2x2 table")
    return [[float(x) for x in row] for row in table]


def expected_counts(table):
    """Expected counts under independence: E[i][j] = row_i * col_j / n."""
    t = _check_2x2(table)
    n = sum(sum(row) for row in t)
    rows = [sum(r) for r in t]
    cols = [t[0][j] + t[1][j] for j in range(2)]
    return [[rows[i] * cols[j] / n for j in range(2)] for i in range(2)]


def chi2_independence(table, yates=False):
    """Pearson chi-squared test of independence for a 2x2 table.

    Returns (statistic, p_value) with the p from the chi2 df=1 distribution.
    yates=True applies the continuity correction |O - E| - 0.5.
    """
    t = _check_2x2(table)
    exp = expected_counts(t)
    if yates:
        stat = sum(
            (abs(t[i][j] - exp[i][j]) - 0.5) ** 2 / exp[i][j]
            for i in range(2)
            for j in range(2)
        )
    else:
        stat = sum(
            (t[i][j] - exp[i][j]) ** 2 / exp[i][j]
            for i in range(2)
            for j in range(2)
        )
    p = _chi2_sf(stat, df=1)
    return stat, p


def _chi2_sf(x, df):
    """Survival function of the chi-squared distribution."""
    if df != 1:
        raise NotImplementedError("only df=1 needed here")
    if x <= 0:
        return 1.0
    return _erfc_sqrt_half_x(x)


def _erfc_sqrt_half_x(x):
    """chi2_{df=1} sf = erfc(sqrt(x/2))."""
    from math import sqrt

    try:
        import mpmath  # optional high-precision path
    except ImportError:
        pass
    # Use math.erfc (accurate to ~1 ulp in double precision)
    from math import erfc

    return erfc(sqrt(x / 2.0))


def fisher_exact_2x2(table):
    """Fisher's exact test for a 2x2 table.

    Two-sided p-value: sum of hypergeometric probabilities of all tables
    with the same margins whose probability is <= that of the observed table.
    Returns (odds_ratio, p_value).
    """
    a, b = int(table[0][0]), int(table[0][1])
    c, d = int(table[1][0]), int(table[1][1])
    row1, col1 = a + b, a + c
    n = row1 + c + d

    def hyp_prob(k):
        # P(first cell = k | margins fixed)
        return comb(col1, k) * comb(n - col1, row1 - k) / comb(n, row1)

    p_obs = hyp_prob(a)
    lo = max(0, col1 - (n - row1))
    hi = min(col1, row1)
    p_two = sum(p for k in range(lo, hi + 1) if (p := hyp_prob(k)) <= p_obs * (1 + 1e-9))

    odds_ratio = (a * d) / (b * c) if b * c else float("inf")
    return odds_ratio, p_two
